-- [SNEAKY FRAMEWORK] — PROPRIETARY VIRTUAL MACHINE EXECUTION CHUNK
local _G = _G or getfenv()
local createVM = (function()

local function createVM(bytecodeBlob)
    local sByte, sChar, sSub, mFloor = string.byte, string.char, string.sub, math.floor
    local tInsert, tRemove, tConcat = table.insert, table.remove, table.concat
    local unpack = (table and table.unpack) or unpack
    local pcall, type, rawget, tonumber, tostring = pcall, type, rawget, tonumber, tostring

    -- 1. Binary stream reader for the packed bytecode blob
    local pos = 1
    local blobLen = #bytecodeBlob

    local function readByte()
        local b = sByte(bytecodeBlob, pos)
        pos = pos + 1
        return b
    end

    local function readVarInt()
        local res = 0
        local shift = 1
        while true do
            local b = sByte(bytecodeBlob, pos)
            pos = pos + 1
            local val = b % 128
            res = res + val * shift
            if b < 128 then break end
            shift = shift * 128
        end
        return res
    end

    local function readSignedVarInt()
        local v = readVarInt()
        if v % 2 == 1 then
            return -mFloor((v + 1) / 2)
        else
            return mFloor(v / 2)
        end
    end

    local function readBytes(len)
        local str = sSub(bytecodeBlob, pos, pos + len - 1)
        pos = pos + len
        return str
    end

    -- Header validation ('S','N','K')
    local m1, m2, m3 = readByte(), readByte(), readByte()
    if m1 ~= 83 or m2 ~= 78 or m3 ~= 75 then
        error("Invalid Sneaky VM chunk header", 2)
    end

    -- Seed (Big-Endian uint32)
    local b1, b2, b3, b4 = readByte(), readByte(), readByte(), readByte()
    local seed = b1 * 16777216 + b2 * 65536 + b3 * 256 + b4

    -- 2. Build Inverse PRNG Opcode Dispatch Table
    -- Base Opcode Enum (Numeric 0..37):
    -- 0:MOVE, 1:LOADK, 2:LOADBOOL, 3:LOADNIL, 4:GETUPVAL, 5:SETUPVAL,
    -- 6:GETGLOBAL, 7:SETGLOBAL, 8:GETTABLE, 9:SETTABLE, 10:NEWTABLE, 11:SELF,
    -- 12:ADD, 13:SUB, 14:MUL, 15:DIV, 16:MOD, 17:POW, 18:UNM, 19:NOT, 20:LEN,
    -- 21:CONCAT, 22:JUMP, 23:EQ, 24:LT, 25:LE, 26:TEST, 27:TESTSET, 28:CALL,
    -- 29:TAILCALL, 30:RETURN, 31:FORLOOP, 32:FORPREP, 33:TFORLOOP, 34:SETLIST,
    -- 35:CLOSURE, 36:VARARG, 37:NOOP
    local opDecode = {}
    do
        local s = seed % 2147483647
        local function rnd(max)
            s = (s * 1664525 + 1013904223) % 4294967296
            return mFloor((s / 4294967296) * max)
        end
        local perm = {}
        for i = 0, 37 do perm[i] = i end
        for i = 37, 1, -1 do
            local j = rnd(i + 1)
            local tmp = perm[i]
            perm[i] = perm[j]
            perm[j] = tmp
        end
        -- perm[rawOp] = encOp => opDecode[encOp] = rawOp
        for rawOp = 0, 37 do
            opDecode[perm[rawOp]] = rawOp
        end
    end

    -- 3. De-obfuscate string constants using rolling PRNG keystream
    local function decodeString(bytes, key)
        local chars = {}
        local k = key
        local bLen = #bytes
        for i = 1, bLen do
            k = (k * 33 + (i - 1) + 7) % 256
            local b = sByte(bytes, i)
            local curK = k
            local res = 0
            local p = 1
            for _ = 1, 8 do
                local b1 = b % 2
                local b2 = curK % 2
                if b1 ~= b2 then res = res + p end
                b = mFloor(b / 2)
                curK = mFloor(curK / 2)
                p = p * 2
            end
            chars[i] = sChar(res)
        end
        return tConcat(chars)
    end

    -- 4. Recursive Prototype Deserializer
    local function readProto()
        local proto = {}
        proto.maxRegs = readVarInt()
        proto.numParams = readVarInt()
        proto.isVararg = readByte()
        local strKey = readByte()

        -- Constants pool
        local nConsts = readVarInt()
        local consts = {}
        for i = 1, nConsts do
            local cType = readByte()
            if cType == 0 then
                consts[i - 1] = nil
            elseif cType == 1 then
                consts[i - 1] = false
            elseif cType == 2 then
                consts[i - 1] = true
            elseif cType == 3 then
                consts[i - 1] = readSignedVarInt()
            elseif cType == 4 then
                local strLen = readVarInt()
                local rawStr = readBytes(strLen)
                consts[i - 1] = tonumber(rawStr) or 0
            elseif cType == 5 then
                local strLen = readVarInt()
                local rawBytes = readBytes(strLen)
                consts[i - 1] = decodeString(rawBytes, strKey)
            end
        end
        proto.resolvedConsts = consts

        -- Upvalues
        local nUpvals = readVarInt()
        local upvals = {}
        for i = 1, nUpvals do
            upvals[i] = {
                isLocal = readByte(),
                index = readVarInt()
            }
        end
        proto.upvalues = upvals

        -- Instructions: [rawOp, a, b, c]
        local nInsts = readVarInt()
        local insts = {}
        for i = 1, nInsts do
            local encOp = readByte()
            local rawOp = opDecode[encOp] or 37
            local a = readVarInt()
            local b = readSignedVarInt()
            local c = readSignedVarInt()
            insts[i] = { rawOp, a, b, c }
        end
        proto.instructions = insts

        -- Child prototypes
        local nProtos = readVarInt()
        local protos = {}
        for i = 1, nProtos do
            protos[i] = readProto()
        end
        proto.prototypes = protos

        return proto
    end

    local rootProto = readProto()

    -- 5. Closure and Execution Frame instantiation
    local function instantiateClosure(proto, parentUpvalues, parentStack)
        local upvalues = {}
        for i = 1, #proto.upvalues do
            local uDef = proto.upvalues[i]
            if uDef.isLocal == 1 then
                local reg = uDef.index
                upvalues[i - 1] = {
                    get = function() return parentStack[reg] end,
                    set = function(v) parentStack[reg] = v end
                }
            else
                upvalues[i - 1] = parentUpvalues[uDef.index]
            end
        end

        local function executeFunction(...)
            local stack = {}
            local varargs = { ... }
            local nArgs = select("#", ...)
            local numParams = proto.numParams or 0
            local top = (nArgs > numParams) and nArgs or numParams

            -- Pass args into stack registers R0..Rn
            for i = 1, nArgs do
                stack[i - 1] = varargs[i]
            end

            local pc = 1
            local insts = proto.instructions
            local nInsts = #insts
            local consts = proto.resolvedConsts

            local function getRK(idx)
                if idx >= 1000000 then
                    return consts[idx - 1000000]
                else
                    return stack[idx]
                end
            end

            -- Main VM dispatch loop (100% Numeric comparison, zero opcode names)
            while pc <= nInsts do
                local inst = insts[pc]
                local op = inst[1]
                local a = inst[2]
                local b = inst[3]
                local c = inst[4]
                pc = pc + 1

                if op == 0 then -- MOVE
                    stack[a] = stack[b]

                elseif op == 1 then -- LOADK
                    stack[a] = consts[b]

                elseif op == 2 then -- LOADBOOL
                    stack[a] = (b ~= 0)
                    if c ~= 0 then pc = pc + 1 end

                elseif op == 3 then -- LOADNIL
                    for r = a, b do
                        stack[r] = nil
                    end

                elseif op == 4 then -- GETUPVAL
                    local uv = upvalues[b]
                    if uv ~= nil then
                        stack[a] = uv.get()
                    end

                elseif op == 5 then -- SETUPVAL
                    local uv = upvalues[b]
                    if uv ~= nil then
                        uv.set(stack[a])
                    end

                elseif op == 6 then -- GETGLOBAL
                    local name = consts[b]
                    stack[a] = _G[name]

                elseif op == 7 then -- SETGLOBAL
                    local name = consts[b]
                    _G[name] = stack[a]

                elseif op == 8 then -- GETTABLE
                    local tbl = stack[b]
                    local key = getRK(c)
                    if tbl ~= nil and key ~= nil then
                        stack[a] = tbl[key]
                    else
                        stack[a] = nil
                    end

                elseif op == 9 then -- SETTABLE
                    local tbl = stack[a]
                    local key = getRK(b)
                    local val = getRK(c)
                    if tbl ~= nil and key ~= nil then
                        tbl[key] = val
                    end

                elseif op == 10 then -- NEWTABLE
                    stack[a] = {}

                elseif op == 11 then -- SELF
                    local tbl = stack[b]
                    stack[a + 1] = tbl
                    local key = getRK(c)
                    if tbl ~= nil and key ~= nil then
                        stack[a] = tbl[key]
                    else
                        stack[a] = nil
                    end

                elseif op == 12 then -- ADD
                    stack[a] = getRK(b) + getRK(c)

                elseif op == 13 then -- SUB
                    stack[a] = getRK(b) - getRK(c)

                elseif op == 14 then -- MUL
                    stack[a] = getRK(b) * getRK(c)

                elseif op == 15 then -- DIV
                    stack[a] = getRK(b) / getRK(c)

                elseif op == 16 then -- MOD
                    stack[a] = getRK(b) % getRK(c)

                elseif op == 17 then -- POW
                    stack[a] = getRK(b) ^ getRK(c)

                elseif op == 18 then -- UNM
                    stack[a] = -stack[b]

                elseif op == 19 then -- NOT
                    stack[a] = not stack[b]

                elseif op == 20 then -- LEN
                    local v = stack[b]
                    if type(v) == "table" or type(v) == "string" then
                        stack[a] = #v
                    else
                        stack[a] = 0
                    end

                elseif op == 21 then -- CONCAT
                    local v1 = getRK(b)
                    local v2 = getRK(c)
                    stack[a] = tostring(v1 ~= nil and v1 or "") .. tostring(v2 ~= nil and v2 or "")

                elseif op == 22 then -- JUMP
                    pc = pc + b

                elseif op == 23 then -- EQ
                    local v1 = getRK(b)
                    local v2 = getRK(c)
                    if (v1 == v2) ~= (a ~= 0) then
                        pc = pc + 1
                    end

                elseif op == 24 then -- LT
                    local v1 = getRK(b)
                    local v2 = getRK(c)
                    local res = false
                    if type(v1) == "number" and type(v2) == "number" then
                        res = (v1 < v2)
                    elseif type(v1) == "string" and type(v2) == "string" then
                        res = (v1 < v2)
                    else
                        local ok, comp = pcall(function() return v1 < v2 end)
                        if ok then res = comp end
                    end
                    if res ~= (a ~= 0) then
                        pc = pc + 1
                    end

                elseif op == 25 then -- LE
                    local v1 = getRK(b)
                    local v2 = getRK(c)
                    local res = false
                    if type(v1) == "number" and type(v2) == "number" then
                        res = (v1 <= v2)
                    elseif type(v1) == "string" and type(v2) == "string" then
                        res = (v1 <= v2)
                    else
                        local ok, comp = pcall(function() return v1 <= v2 end)
                        if ok then res = comp end
                    end
                    if res ~= (a ~= 0) then
                        pc = pc + 1
                    end

                elseif op == 26 then -- TEST
                    local val = stack[a]
                    local boolVal = (val and val ~= false) and 1 or 0
                    if boolVal ~= c then
                        pc = pc + 1
                    end

                elseif op == 27 then -- TESTSET
                    local val = stack[b]
                    local boolVal = (val and val ~= false) and 1 or 0
                    if boolVal ~= c then
                        pc = pc + 1
                    else
                        stack[a] = val
                    end

                elseif op == 28 then -- CALL
                    local func = stack[a]
                    local callArgs = {}
                    local nParams = b - 1
                    if b == 0 then
                        nParams = (top > (a + 1)) and (top - (a + 1)) or 0
                    end
                    for i = 1, nParams do
                        callArgs[i] = stack[a + i]
                    end

                    local function doCall()
                        if c == 1 then
                            func(unpack(callArgs, 1, nParams))
                        elseif c > 1 then
                            local rets = { func(unpack(callArgs, 1, nParams)) }
                            for i = 1, c - 1 do
                                stack[a + i - 1] = rets[i]
                            end
                        else
                            local rets = { func(unpack(callArgs, 1, nParams)) }
                            for i = 1, #rets do
                                stack[a + i - 1] = rets[i]
                            end
                            top = a + #rets
                        end
                    end
                    local ok, cErr = pcall(doCall)
                    if not ok then
                        error(tostring(cErr), 0)
                    end

                elseif op == 29 then -- TAILCALL
                    local func = stack[a]
                    local callArgs = {}
                    local nParams = b - 1
                    if b == 0 then
                        nParams = (top > (a + 1)) and (top - (a + 1)) or 0
                    end
                    for i = 1, nParams do
                        callArgs[i] = stack[a + i]
                    end
                    return func(unpack(callArgs, 1, nParams))

                elseif op == 30 then -- RETURN
                    if b == 1 then
                        return
                    elseif b > 1 then
                        local rets = {}
                        for i = 1, b - 1 do
                            rets[i] = stack[a + i - 1]
                        end
                        return unpack(rets, 1, b - 1)
                    else
                        local rets = {}
                        local count = (top > a) and (top - a) or 0
                        for i = 1, count do
                            rets[i] = stack[a + i - 1]
                        end
                        return unpack(rets, 1, count)
                    end

                elseif op == 31 then -- FORLOOP
                    local step = stack[a + 2]
                    local limit = stack[a + 1]
                    local init = stack[a] + step
                    stack[a] = init

                    local stop = false
                    if step > 0 then
                        stop = (init > limit)
                    else
                        stop = (init < limit)
                    end

                    if not stop then
                        pc = pc + b
                        stack[a + 3] = init
                    end

                elseif op == 32 then -- FORPREP
                    stack[a] = stack[a] - stack[a + 2]
                    pc = pc + b

                elseif op == 33 then -- TFORLOOP
                    local iterFunc = stack[a]
                    local state = stack[a + 1]
                    local initVal = stack[a + 2]
                    local rets = { iterFunc(state, initVal) }
                    local varCount = c
                    for i = 1, varCount do
                        stack[a + 2 + i] = rets[i]
                    end
                    if stack[a + 3] ~= nil then
                        stack[a + 2] = stack[a + 3]
                    else
                        pc = pc + 1
                    end

                elseif op == 34 then -- SETLIST
                    local tbl = stack[a]
                    local count = b
                    if count == 0 then count = #stack - a end
                    local base = (c - 1) * 50
                    for i = 1, count do
                        tbl[base + i] = stack[a + i]
                    end

                elseif op == 35 then -- CLOSURE
                    local childProto = proto.prototypes[b + 1]
                    stack[a] = instantiateClosure(childProto, upvalues, stack)

                elseif op == 36 then -- VARARG
                    local varargOffset = numParams
                    local varargCount = (nArgs > varargOffset) and (nArgs - varargOffset) or 0
                    if c > 0 then
                        local tbl = stack[c - 1]
                        if tbl ~= nil then
                            for i = 1, varargCount do
                                tbl[a + i - 1] = varargs[varargOffset + i]
                            end
                        end
                    elseif b == 0 then
                        for i = 1, varargCount do
                            stack[a + i - 1] = varargs[varargOffset + i]
                        end
                        top = a + varargCount
                    else
                        local count = b - 1
                        for i = 1, count do
                            stack[a + i - 1] = varargs[varargOffset + i]
                        end
                    end

                elseif op == 37 then -- NOOP
                    -- Inert polymorphic instruction
                end
            end
        end

        return executeFunction
    end

    local rootFunc = instantiateClosure(rootProto, {}, {})
    return rootFunc
end

return createVM

end)()

local _bChunk = ""
local _bBlob = (_bChunk:gsub("..", function(cc) return string.char(tonumber(cc, 16)) end))
local vmMain = createVM(_bBlob)
return vmMain(...)
